function normalizeArabic(t) {
  if (t === null || t === undefined) return '';
  return String(t)
    .replace(/[\u0623\u0625\u0622]/g, '\u0627')
    .replace(/\u0629/g, '\u0647')
    .replace(/\u0649/g, '\u064a')
    .replace(/\u0640/g, '')
    .replace(/[\u064B-\u0652]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
// Normalize BEFORE any matching, extraction, or search — always.
// Merges: webhook body (draft) + owner row + tenant row, by explicit node references.
// draft_kind is one of: project | item | policy (fixed whitelist, never a free table name).
const body = $('Webhook').first().json.body ?? {};
const owner = $('Identify Owner').first().json ?? {};
const tenant = $('Load Tenant Status').first().json ?? {};
if (!owner.id || owner.role !== 'owner') throw new Error('intake_rejected: caller is not a registered owner of this tenant');
if (tenant.status === 'paused' || tenant.status === 'cancelled') throw new Error('intake_rejected: tenant is not active');
const ALLOWED_KINDS = ['project', 'item', 'policy'];
if (!ALLOWED_KINDS.includes(body.draft_kind)) throw new Error('intake_rejected: draft_kind not allowed');
const normalized = {};
for (const [k, v] of Object.entries(body.draft_fields ?? {})) {
  normalized[k] = typeof v === 'string' ? normalizeArabic(v) : v;
}
return [{ json: { owner_id: owner.id, tenant_id: tenant.id, sector_code: tenant.sector_code, draft_kind: body.draft_kind, draft_fields: body.draft_fields ?? {}, normalized_fields: normalized, confirmed_by_owner: body.confirmed_by_owner === true } }];

// Builds the draft the owner must confirm. NOTHING is saved by this node.
// Confirmation wording shown to the owner: «يعني كذا، صح؟» followed by the draft.
// If confirmed_by_owner is false, the action is 'ask_confirm' and the Save node below
// becomes a no-op by its SQL guard; the Respond node returns the draft for confirmation.
const d = $json;
const action = d.confirmed_by_owner ? 'save' : 'ask_confirm';
const confirmation_text = 'يعني كذا، صح؟\n' + JSON.stringify(d.draft_fields, null, 2);
return [{ json: { ...d, action, confirmation_text } }];

const d = $('Build Draft and Confirmation').first().json;
return [{ json: {
  tenant_id: d.tenant_id,
  action: d.action,
  saved: d.action === 'save',
  confirmation_text: d.action === 'save' ? 'تم الحفظ.' : d.confirmation_text
} }];
